  "trigger": "外部可控字符串经 Jinja2 模板的 urlize filter 渲染，且包含可触发正则回溯的长模式时触发 ReDoS。",
  "preconditions": [
    "Jinja2 版本低于 2.11.3",
    "模板中使用了 urlize filter 且其参数来自外部可控输入",
    "输入包含可触发正则回溯的长字符串或特定标点模式"
  ],
  "exploit_evidence": [
    {
      "src": 7,
      "kind": "poc",
      "quote": "Snyk has a proof-of-concept or detailed explanation of how to exploit this vulnerability."
    }
  ],
  "fixed_version": "2.11.3",
  "summary_zh": "Jinja2 2.10 的 urlize 过滤器有 ReDoS，外部输入可致 DoS，请升级 2.11.3 或禁用 urlize。"
}
